package com.sivion.api.finance.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="finance_payments") public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="tenant_id",nullable=false) Long tenantId; @Column(nullable=false) String paymentNumber; @Column(nullable=false) Long invoiceId; @Column(nullable=false) BigDecimal amount; @Column(nullable=false) String method; @Column(nullable=false) Instant paidAt=Instant.now(); public Long getId(){return id;} public Long getTenantId(){return tenantId;} public void setTenantId(Long v){tenantId=v;} public String getPaymentNumber(){return paymentNumber;} public void setPaymentNumber(String v){paymentNumber=v;} public Long getInvoiceId(){return invoiceId;} public void setInvoiceId(Long v){invoiceId=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public String getMethod(){return method;} public void setMethod(String v){method=v;} public Instant getPaidAt(){return paidAt;} }
